// Firma di Fireflies (Webhooks V2): X-Hub-Signature = "sha256=" + HMAC-SHA256(corpo grezzo, segreto).
// Serve NODE_FUNCTION_ALLOW_BUILTIN=crypto nell'istanza n8n.
const crypto = require('crypto');
const secret = $env.FIREFLIES_WEBHOOK_SECRET;
if (!secret) throw new Error('Manca FIREFLIES_WEBHOOK_SECRET');
const item = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const given = String((item.json.headers || {})['x-hub-signature'] || '');
const ok = given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
if (!ok) throw new Error('Firma Fireflies non valida');
const body = JSON.parse(raw.toString('utf8'));
// Solo le trascrizioni completate; gli altri eventi si ignorano.
if (body.event !== 'meeting.transcribed' || !body.meeting_id) return [];
return [{ json: { meetingId: body.meeting_id } }];

// Dal formato Fireflies a quello del webhook OCRA (vedi docs/integrazioni/FIREFLIES.md).
// Codice PO del progetto: tra parentesi quadre nel titolo dell'evento, es. «Produzione Nora [FL/COMUNIC/01-2026/NORA/E]».
const PO = /\[([^\]]{2,200})\]/;
return $input.all().map(({ json }) => {
  const t = json.data && json.data.transcript;
  if (!t) throw new Error('Fireflies: trascrizione non trovata ' + JSON.stringify(json.errors || ''));
  const sentences = t.sentences || [];
  const durationSec = typeof t.duration === 'number' ? Math.round(t.duration * 60) : null;
  // start_time è in secondi; se sembra in millisecondi (molto oltre la durata) si converte.
  const maxStart = Math.max(0, ...sentences.map((s) => Number(s.start_time) || 0));
  const scale = durationSec && maxStart > durationSec * 2 ? 1000 : 1;
  const attendees = (t.meeting_attendees || []).map((a) => a.displayName || a.name || a.email).filter(Boolean);
  const speakers = [...new Set(sentences.map((s) => s.speaker_name).filter(Boolean))];
  const title = t.title || '';
  const code = title.match(PO);
  return {
    json: {
      id: 'fireflies:' + t.id,
      title: title.replace(PO, '').trim() || null,
      date: t.dateString || null,
      durationSec,
      participants: attendees.length ? attendees : speakers,
      project: code ? code[1].trim() : null,
      sentences: sentences.map((s) => ({
        speaker: s.speaker_name || null,
        text: s.text || '',
        start: s.start_time == null ? null : Number(s.start_time) / scale,
      })),
    },
  };
});
